mapper.select:
SELECT c.id, c.contract_no, c.contract_name, c.contract_type, c.customer_id, c.opportunity_id, c.quote_id, c.contract_amount, c.received_amount, c.invoiced_amount, c.status, c.sign_date, c.start_date, c.end_date, c.sign_user_id, c.our_sign_user_id, c.owner_id, c.file_url, c.remark, c.create_time, c.update_time, cust.customer_name, opp.opp_name as opportunity_name, q.quote_name, u1.user_name AS owner_name, u2.user_name AS our_sign_user_name, CASE WHEN c.contract_amount > 0 THEN ROUND(c.received_amount / c.contract_amount * 100, 2) ELSE 0 END AS received_progress, CASE WHEN c.contract_amount > 0 THEN ROUND(c.invoiced_amount / c.contract_amount * 100, 2) ELSE 0 END AS invoiced_progress FROM crm_contract c LEFT JOIN crm_customer cust ON c.customer_id = cust.id LEFT JOIN crm_opportunity opp ON c.opportunity_id = opp.id LEFT JOIN crm_quote q ON c.quote_id = q.id LEFT JOIN sys_user u1 ON c.owner_id = u1.id LEFT JOIN sys_user u2 ON c.our_sign_user_id = u2.id WHERE 1=1
AND c.contract_name LIKE CONCAT('%', #{query.contractName}, '%')
AND c.contract_no LIKE CONCAT('%', #{query.contractNo}, '%')
AND c.customer_id = #{query.customerId}
AND c.opportunity_id = #{query.opportunityId}
AND c.contract_type = #{query.contractType}
AND c.status = #{query.status}
AND c.owner_id = #{query.ownerId}
AND c.sign_date >= #{query.signDateStart}
AND c.sign_date <= #{query.signDateEnd}
ORDER BY c.create_time DESC

SELECT c.id, c.contract_no, c.contract_name, c.customer_id, c.contract_amount, c.received_amount, c.invoiced_amount, c.status, c.owner_id, cust.customer_name, u1.user_name AS owner_name FROM crm_contract c LEFT JOIN crm_customer cust ON c.customer_id = cust.id LEFT JOIN sys_user u1 ON c.owner_id = u1.id WHERE 1=1
AND c.status = #{status}
ORDER BY c.create_time DESC
